        if (k > maxA) {
            System.out.println(0);
            return;
        }
        int M = Math.max(maxA, k) + 1;
        int[] cnt = new int[M];
        for (int v : a) {
            cnt[v]++;
        }
        // 预处理2的幂，最大到n
        long[] pow2 = new long[n + 1];
        pow2[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow2[i] = (pow2[i-1] * 2) % MOD;
        }
        // f[i] = 倍数个数
        int[] f = new int[M];
        for (int i = 1; i < M; i++) {
            for (int j = i; j < M; j += i) {
