            }
        }
        // g[i] = (2^f[i] - 1) % MOD
        long[] g = new long[M];
        for (int i = 1; i < M; i++) {
            g[i] = (pow2[f[i]] - 1 + MOD) % MOD;
        }
        // dp倒推
        long[] dp = new long[M];
        for (int i = M - 1; i >= 1; i--) {
            dp[i] = g[i];
            for (int j = i * 2; j < M; j += i) {
                dp[i] = (dp[i] - dp[j] + MOD) % MOD;
            }
        }
